//! Actions-only explicit-owner create protocol, shared journal and READ brands.
#[path="group_owner_only_tests.rs"]
mod owner_only;
use super::*;
use n::{group_create::{self as create,NativeGroupCreateConfig as CPolicy},group_management::{PublicProperty,PropertyValue},group_create_store,relation_journal::{RelationIntent,IntentAdmission,RelationConfiguration},rpc_im::ImQuery};
const GROUP:&[u8]=b"811111111-922222222";
fn cpolicy()->CPolicy{CPolicy{create:true,read_properties:true}}
fn installed()->Fixture{let mut f=Fixture::new(true);f.backend.close();let mut b=OfflineBackend::new(f.owner.clone());b.claim_common_transport().unwrap();b.bind_common_identity(b"AccountEntry").unwrap();let cfg=NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:30000,receive_info:false,directory_queries:false})};let policy=NativeReceiverPolicy::capture(&cfg).unwrap().with_creation_properties(cpolicy()).unwrap();b.arm_native_receivers(NativeReceiverSetup::capture(policy,true,None).unwrap()).unwrap();f.scope=b.connection_scope();let login=b.prepare_login(login(),&[]).unwrap();b.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(login.call_id,&login_result()),0).unwrap();b.configure_native_receivers(7).unwrap();f.backend=b;f.temp.database.with_conn(group_create_store::initialize_schema).unwrap();f}
fn members(owner:&[u8])->[Relation<'_>;2]{[Relation{label:owner,flags:0,first:b"explicit-owner-name",second:b"",properties:vec![]},Relation{label:b"1_2",flags:1,first:b"explicit-member-name",second:b"",properties:vec![]}]}
fn prep(f:&Fixture,nonce:&str,owner:&[u8],read:bool)->Result<IntentAdmission,&'static str>{let m=Arc::new(RelationMessage::capture_creation(&f.scope,"private-created-name",1,owner,&members(owner),&[],nonce,read,cpolicy())?);let cfg=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope)))?);RelationIntent::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),m,cfg,f.gate.clone(),Instant::now()+Duration::from_secs(30))}
fn bind(f:&Fixture,nonce:&str,owner:&[u8],read:bool)->(Arc<RelationIntent>,Arc<RelationAction>,Arc<RelationPermit>){let IntentAdmission::Fresh(i)=prep(f,nonce,owner,read).unwrap()else{panic!("fresh")};let PreparedRelation::Fresh(a)=i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),cpolicy()).unwrap()else{panic!("fresh")};let p=a.permit(cpolicy()).unwrap();(i,a,p)}
fn result(accepted:bool,group:&[u8],reason:&[u8])->Vec<u8>{let mut w=Writer::new();w.boolean(accepted).unwrap();w.bytes(group).unwrap();w.u32(0xf123_4567).unwrap();w.bytes(b"private-single-first").unwrap();w.bytes(b"private-single-second").unwrap();w.properties(&[RpcProperty{key:b"opaque",value:b"not-a-grant"}]).unwrap();w.i64(i64::MIN).unwrap();w.i64(i64::MAX).unwrap();w.bytes(reason).unwrap();w.properties(&[RpcProperty{key:b"footer",value:b"not-sdk-auth"}]).unwrap();w.finish().expose_to_transport().to_vec()}
fn confirmed(f:&mut Fixture,read:bool)->n::relation_journal::RelationWriteView{let(_i,_a,p)=bind(f,&"c".repeat(32),b"fixture-user",read);let packet=write(f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(packet.call_id,&result(true,GROUP,b"")),0).unwrap();let r=f.backend.take_relation_replies().pop().unwrap();p.resolve(&r).unwrap()}
fn property_result(accepted:bool)->Vec<u8>{let mut w=Writer::new();w.boolean(accepted).unwrap();w.properties(&[RpcProperty{key:b"Group.Org.Name",value:b"private-observed-name"}]).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
#[test]fn group_create_explicit_owner_map_and_properties_are_native_versioned_not_id_plus_maps(){let f=installed();let input=create::CreateInput::capture(&f.scope,"name",2,b"fixture-user",&members(b"fixture-user"),&[PublicProperty{key:"UpdateMethod",value:PropertyValue::Number(2)}],true).unwrap();let bytes=input.arguments(b"fixture-user").unwrap();let mut r=Reader::versioned(&bytes).unwrap();assert_eq!(r.u32().unwrap(),2);assert_eq!(r.bytes().unwrap(),b"1_2");assert_eq!(r.u32().unwrap(),1);assert_eq!(r.bytes().unwrap(),b"explicit-member-name");r.bytes().unwrap();r.properties().unwrap();assert_eq!(r.bytes().unwrap(),b"fixture-user");assert_eq!(r.u32().unwrap(),0);assert_eq!(r.bytes().unwrap(),b"explicit-owner-name");r.bytes().unwrap();r.properties().unwrap();let props=r.properties().unwrap();assert_eq!(props.len(),3);assert_eq!(props.iter().find(|p|p.key==b"Group.Org.Type").unwrap().value,b"LargeGroup");assert_eq!(props.iter().find(|p|p.key==b"Group.Org.Name").unwrap().value,b"name");assert_eq!(props.iter().find(|p|p.key==b"Group.Org.Notify").unwrap().value,b"Mixed");r.finish().unwrap();assert!(input.arguments(b"another-native-uid").is_err());}
#[test]fn group_create_missing_owner_invalid_members_or_conflicting_name_type_fail_without_budget(){let f=installed();assert!(create::CreateInput::capture(&f.scope,"name",1,b"fixture-user",&members(b"different"),&[],false).is_err());assert!(create::CreateInput::capture(&f.scope,"",1,b"fixture-user",&members(b"fixture-user"),&[],false).is_err());assert!(create::CreateInput::capture(&f.scope,"name",5,b"fixture-user",&members(b"fixture-user"),&[],false).is_err());assert!(create::CreateInput::capture(&f.scope,"name",1,b"fixture-user",&members(b"fixture-user"),&[PublicProperty{key:"Name",value:PropertyValue::Text("override")}],false).is_err());let mut m=members(b"fixture-user");m[0].flags=1;assert!(create::CreateInput::capture(&f.scope,"name",1,b"fixture-user",&m,&[],false).is_err());m[0].flags=0;m[1].label=b"[phone:+12345@foreign.invalid]";assert!(create::CreateInput::capture(&f.scope,"name",1,b"fixture-user",&m,&[],false).is_err());assert_eq!(f.scope.native_rpc_resources(),(0,0));}
#[test]fn group_create_policy_is_default_off_and_does_not_inherit_management_or_directory(){let cert=n::tls_engine::tests::Certificates::generate("IP:127.0.0.1");let mut c=n::account_config::tests::native_fixture(&cert.root,"127.0.0.1",1);let raw=c.encode_private().unwrap();assert!(c.profile.group_creation.is_none());assert!(!String::from_utf8_lossy(&raw).contains("group_creation"));assert_eq!(n::account_config::AccountConfig::decode_private(&raw).unwrap().encode_private().unwrap(),raw);c.profile.group_creation=Some(cpolicy());assert!(c.runtime_profile().is_err());c.profile.client_ex=true;c.profile.incoming=None;c.profile.native_receivers=Some(NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:3000,receive_info:false,directory_queries:false})});assert!(c.runtime_profile().is_ok());assert!(c.profile.group_management.is_none()&&c.profile.relation_updates.is_none());assert!((CPolicy{create:false,read_properties:true}).validate().is_err());}
#[test]fn group_create_shared_preparing_blocks_members_and_management_in_both_directions(){let f=installed();let IntentAdmission::Fresh(i)=prep(&f,&"c".repeat(32),b"fixture-user",true).unwrap()else{panic!()};let cfg=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope))).unwrap());let message=Arc::new(RelationMessage::capture(&f.scope,None,&[relation(b"1_2")],&[],&[],&"d".repeat(32),policy()).unwrap());assert_eq!(RelationIntent::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),message,cfg,f.gate.clone(),Instant::now()+Duration::from_secs(30)).err(),Some("app_account_relation_preparing"));assert_eq!(prep(&f,&"d".repeat(32),b"fixture-user",false).err(),Some("app_account_relation_preparing"));drop(i);let a=action(&f);assert_eq!(prep(&f,&"d".repeat(32),b"fixture-user",false).err(),Some("app_account_relation_uncertain"));drop(a);}
#[test]fn group_create_same_nonce_changed_owner_or_after_read_consent_is_conflict_not_new_write(){let f=installed();let IntentAdmission::Fresh(_i)=prep(&f,&"c".repeat(32),b"fixture-user",true).unwrap()else{panic!()};assert_eq!(prep(&f,&"c".repeat(32),b"different",true).err(),Some("app_account_relation_nonce_conflict"));assert_eq!(prep(&f,&"c".repeat(32),b"fixture-user",false).err(),Some("app_account_relation_nonce_conflict"));}
#[test]fn group_create_wrong_expected_owner_retires_not_sent_before_positive_rpc_id(){let mut f=installed();let IntentAdmission::Fresh(i)=prep(&f,&"c".repeat(32),b"wrong-expected-owner",false).unwrap()else{panic!()};let PreparedRelation::Fresh(a)=i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),cpolicy()).unwrap()else{panic!()};assert_eq!(a.permit(cpolicy()).err(),Some("app_account_group_create_owner_mismatch"));a.cancel();let rows=f.temp.database.with_conn(|c|n::relation_journal::history(c,f.run.line_id(),128)).unwrap();assert_eq!(rows[0].state,"not_sent");assert!(rows[0].base_time.is_none());let packet=f.backend.prepare_im_read(Arc::new(ImQuery::refresh(&[],-1).unwrap()),f.gate.clone(),Instant::now()+Duration::from_secs(30)).unwrap();assert_eq!(packet.call_id,2);}
#[test]fn group_create_current_matched_result_commits_private_group_and_true_signed_times_without_roster(){let mut f=installed();let v=confirmed(&mut f,true);assert_eq!(v.state,"confirmed");assert_eq!(v.management.as_ref().unwrap().operation,"create");assert_eq!(v.management.as_ref().unwrap().properties,2);assert_eq!((v.additions,v.updates,v.removals),(0,0,0));assert_eq!(v.base_time.as_deref(),Some("-9223372036854775808"));assert_eq!(v.update_time.as_deref(),Some("9223372036854775807"));assert!(v.creation_receipt.is_some());let body=serde_json::to_string(&v).unwrap();for secret in ["811111111-922222222","fixture-user","private-created-name","private-single-first","opaque"]{assert!(!body.contains(secret));}assert_eq!(f.count(),0);let events=f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap();assert_eq!(events.len(),1);assert_eq!(events[0].event_type,"app_voice.group_created");assert!(!events[0].payload_json.contains("811111111-922222222"));}
#[test]fn group_create_negative_or_reason_result_never_mints_read_brand_or_stores_groupid(){for(accepted,reason)in[(false,b"".as_slice()),(true,b"refused".as_slice())]{let mut f=installed();let(_i,_a,p)=bind(&f,&"c".repeat(32),b"fixture-user",true);let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(packet.call_id,&result(accepted,GROUP,reason)),0).unwrap();let r=f.backend.take_relation_replies().pop().unwrap();let v=p.resolve(&r).unwrap();assert_eq!(v.state,"rejected");assert!(v.creation_receipt.is_none());let events=f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap();assert_eq!(events.len(),1);assert_eq!(events[0].event_type,"app_voice.group_create_rejected");let group:Option<Vec<u8>>=f.temp.database.with_conn(|c|c.query_row("SELECT group_id FROM app_voice_group_creations",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert!(group.is_none());}}
#[test]fn group_create_history_replay_cannot_construct_or_renew_property_read_brand(){let mut f=installed();let v=confirmed(&mut f,true);let IntentAdmission::Replay(id)=prep(&f,&"c".repeat(32),b"fixture-user",true).unwrap()else{panic!("history only")};let view=f.temp.database.with_conn(|c|n::relation_journal::historical_view(c,f.run.line_id(),id)).unwrap();assert_eq!(view.id,v.id);assert!(view.creation_receipt.is_none());assert!(v.creation_receipt.unwrap().current());}
#[test]fn group_create_followup_query_uses_exact_returned_group_and_original_empty_prefix_only_once(){let mut f=installed();let v=confirmed(&mut f,true);let receipt=v.creation_receipt.unwrap();let input=f.scope.reserve_native_rpc(receipt.group().len()+256).unwrap();let q=Arc::new(ImQuery::created_properties(receipt.clone(),input).unwrap());let _wait=n::group_create_read::CreationReadWait::original(receipt.clone(),q.clone());let packet=f.backend.prepare_im_read(q.clone(),f.gate.clone(),receipt.deadline()).unwrap();let r=decode_request(&packet.packets[0].expose_to_transport()[1..]).unwrap();assert_eq!(r.method,b"getPropsPrefixs.GroupServer.Group");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),GROUP);assert_eq!(a.u32().unwrap(),1);assert_eq!(a.bytes().unwrap(),b"");a.finish().unwrap();let input=f.scope.reserve_native_rpc(256).unwrap();assert!(ImQuery::created_properties(receipt.clone(),input).is_err());assert!(f.backend.prepare_im_read(q.clone(),f.gate.clone(),receipt.deadline()).is_err(),"the same Arc cannot mint another request");f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(packet.call_id,&property_result(true)),0).unwrap();let r=f.backend.take_im_replies().pop().unwrap();let read=receipt.outcome(&r).unwrap();assert_eq!(read.state,"observed");assert_eq!(read.properties,Some(1));assert!(n::im_inbox::CursorSession::from_refresh(f.run.clone(),f.gate.clone(),&r).is_err());assert_eq!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap().len(),1);}
#[test]fn group_create_property_false_and_config_retirement_cannot_change_confirmed_write(){let mut f=installed();let v=confirmed(&mut f,true);let receipt=v.creation_receipt.unwrap();let input=f.scope.reserve_native_rpc(256).unwrap();let q=Arc::new(ImQuery::created_properties(receipt.clone(),input).unwrap());let _wait=n::group_create_read::CreationReadWait::original(receipt.clone(),q.clone());let p=f.backend.prepare_im_read(q,f.gate.clone(),receipt.deadline()).unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&property_result(false)),0).unwrap();let reply=f.backend.take_im_replies().pop().unwrap();assert_eq!(receipt.outcome(&reply).unwrap().state,"rejected");let state:i64=f.temp.database.with_conn(|c|c.query_row("SELECT state FROM app_voice_relation_writes",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(state,1);f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();assert!(!receipt.current());assert!(receipt.outcome(&reply).is_err());}
#[test]fn group_create_initial_members_do_not_override_separate_management_grant(){let f=installed();let IntentAdmission::Fresh(i)=prep(&f,&"c".repeat(32),b"fixture-user",false).unwrap()else{panic!()};assert!(i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),n::group_management::NativeGroupManagementConfig{set_properties:true,disband:true}).is_err());assert!(i.bind(f.backend.captured_im_binding().unwrap(),f.backend.captured_relation_identity().unwrap(),policy()).is_err());}
#[test]fn group_create_partial_or_submitted_cancel_keeps_same_shared_unknown_not_created_state(){for full in [false,true]{let mut f=installed();let(_i,_a,p)=bind(&f,&"c".repeat(32),b"fixture-user",true);let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));if full{assert!(p.submitted());}p.cancel();let rows=f.temp.database.with_conn(|c|n::relation_journal::history(c,f.run.line_id(),128)).unwrap();assert_eq!(rows[0].state,"uncertain");assert!(rows[0].creation_receipt.is_none());assert!(rows[0].base_time.is_none());assert!(!f.scope.is_open());}}
#[test]fn group_create_result_and_write_event_commit_are_atomic_on_sql_failure(){let mut f=installed();let(_i,_a,p)=bind(&f,&"c".repeat(32),b"fixture-user",true);let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(packet.call_id,&result(true,GROUP,b"")),0).unwrap();let reply=f.backend.take_relation_replies().pop().unwrap();f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_create_event BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.group_created' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();assert!(p.resolve(&reply).is_err());let hash:Option<Vec<u8>>=f.temp.database.with_conn(|c|c.query_row("SELECT reply_hash FROM app_voice_group_creations",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert!(hash.is_none());assert_eq!(f.temp.database.with_conn(|c|n::relation_journal::history(c,f.run.line_id(),128)).unwrap()[0].state,"uncertain");assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap().is_empty());p.cancel();}
#[test]fn group_create_strict_single_relation_result_rejects_truncation_trailing_and_other_operation_envelopes(){let f=installed();let bytes=result(true,GROUP,b"");for end in 0..bytes.len(){let success=create::decode(&f.scope,0,&bytes[..end]).is_ok();let no_optional_footer=bytes.len()-(4+8+6+12);assert_eq!(success,end==no_optional_footer);}let mut trailing=bytes.clone();trailing.push(0);assert!(create::decode(&f.scope,0,&trailing).is_err());assert!(create::decode(&f.scope,1,&bytes).is_err());assert!(create::decode(&f.scope,0,&[0,1,0,0,0,0]).is_err());let mut bad=result(true,b"1_2",b"");assert!(create::decode(&f.scope,0,&bad).is_err());bad[1]=0;assert!(!create::decode(&f.scope,0,&bad).unwrap().accepted);}
#[test]fn group_create_missing_descriptor_or_old_owner_epoch_cannot_authorize_property_read(){let mut f=installed();let v=confirmed(&mut f,true);let receipt=v.creation_receipt.unwrap();f.temp.database.with_conn(|c|c.execute("DELETE FROM app_voice_group_creations",[]).map_err(|_|"fixture")).unwrap();assert!(!receipt.current());assert!(prep(&f,&"d".repeat(32),b"fixture-user",false).is_err());let other=installed();assert!(!receipt.binds(&other.owner,&other.scope,&other.gate));}

#[test]
fn group_create_property_guard_rechecks_actual_short_rpc_deadline_after_sql_wait(){
 let mut f=installed();let receipt=confirmed(&mut f,true).creation_receipt.unwrap();let q=Arc::new(ImQuery::created_properties(receipt.clone(),f.scope.reserve_native_rpc(256).unwrap()).unwrap());let _wait=n::group_create_read::CreationReadWait::original(receipt.clone(),q.clone());
 let short=Instant::now()+Duration::from_millis(100);let packet=f.backend.prepare_im_read(q,f.gate.clone(),short).unwrap();let guard=packet.packets[0].group_event_retention().unwrap();assert!(guard.current(Instant::now()));
 let db=f.temp.database.clone();let(locked,seen)=std::sync::mpsc::channel();let(release,wait)=std::sync::mpsc::channel();let blocker=std::thread::spawn(move||db.with_conn(|_|{locked.send(()).unwrap();wait.recv().unwrap();Ok(())}).unwrap());seen.recv().unwrap();
 let(start,seen)=std::sync::mpsc::channel();let checking=std::thread::spawn(move||{start.send(()).unwrap();guard.current(Instant::now())});seen.recv().unwrap();std::thread::sleep(short.saturating_duration_since(Instant::now())+Duration::from_millis(10));release.send(()).unwrap();blocker.join().unwrap();assert!(!checking.join().unwrap());assert!(receipt.current());assert_eq!(state(&f).0,1);
}
#[test]
fn group_create_channel_retry_keeps_exact_read_holder_until_last_drop_but_cannot_send_after_wait_retirement(){
 use n::{native_channel::{self,HeaderMode,PacketKind,ChannelPacket},reliable_channel::{ChannelCore,ChannelError}};
 let mut f=installed();let receipt=confirmed(&mut f,true).creation_receipt.unwrap();let q=Arc::new(ImQuery::created_properties(receipt.clone(),f.scope.reserve_native_rpc(256).unwrap()).unwrap());let wait=n::group_create_read::CreationReadWait::original(receipt.clone(),q.clone());let now=Instant::now();let end=now+Duration::from_secs(3);let packet=f.backend.prepare_im_read(q.clone(),f.gate.clone(),end).unwrap();let source=&packet.packets[0];let mut channel=ChannelCore::new(0,1460,now+Duration::from_secs(10),Duration::from_secs(2),now).unwrap();let start=channel.next_packet(now).unwrap().unwrap();let seq=native_channel::decode_packet(HeaderMode::Basic,start.expose_to_transport()).unwrap().sequence;
 let remote=native_channel::encode_packet(HeaderMode::Basic,&ChannelPacket{timestamp:None,sequence:0x9000,kind:PacketKind::Start,data_gap:0,ack_sequence:seq,delivered_sequence:seq,inclusive_ack:false,ack_mask:&[],body:&[]}).unwrap();channel.on_packet(remote.expose_to_transport(),now).unwrap();assert!(channel.ready());channel.next_packet(now).unwrap().unwrap();channel.queue_record_retained(source.expose_to_transport(),end,now,source.group_event_retention()).unwrap();let first=channel.next_packet(now).unwrap().unwrap();let retry=channel.next_packet(now+Duration::from_millis(200)).unwrap().unwrap();assert!(first.group_event_packet_current(now));assert!(retry.group_event_retention().is_some());drop(wait);assert!(!retry.group_event_packet_current(Instant::now()));assert_eq!(channel.next_packet(now+Duration::from_millis(400)).err(),Some(ChannelError::Closed));channel.close();f.backend.close();drop(packet);drop(first);drop(q);drop(receipt);assert!(f.scope.native_rpc_resources().1>0);drop(retry);assert_eq!(f.scope.native_rpc_resources(),(0,0));assert_eq!(state(&f).0,1);
}
#[test]
fn group_create_changed_descriptor_blocks_first_packet_and_corrupt_confirmation_does_not_authorize_read(){
 for sql in ["UPDATE app_voice_group_creations SET initial_members=3","UPDATE app_voice_group_creations SET read_properties=0","UPDATE app_voice_group_creations SET body_hash=zeroblob(32)"]{let mut f=installed();let(_i,_a,p)=bind(&f,&"c".repeat(32),b"fixture-user",true);let frame=write(&mut f,&p);f.temp.database.with_conn(|c|c.execute(sql,[]).map_err(|_|"fixture")).unwrap();assert!(!frame.packets[0].group_event_packet_current(Instant::now()));assert!(!p.begin_write(frame.call_id));assert_eq!(state(&f).0,0);}
 for sql in ["UPDATE app_voice_relation_intents SET body_hash=zeroblob(32)","UPDATE app_voice_relation_writes SET intent_hash=zeroblob(32)","UPDATE app_voice_relation_writes SET update_time=0","UPDATE app_voice_relation_writes SET result_code=1","UPDATE app_voice_group_creations SET reply_hash=zeroblob(32)","DELETE FROM app_voice_relation_intents"]{let mut f=installed();let receipt=confirmed(&mut f,true).creation_receipt.unwrap();f.temp.database.with_conn(|c|c.execute(sql,[]).map_err(|_|"fixture")).unwrap();assert!(!receipt.current());assert!(ImQuery::created_properties(receipt,f.scope.reserve_native_rpc(256).unwrap()).is_err());assert_eq!(state(&f).0,1);}
}
#[test]
fn group_create_competing_member_property_disband_and_create_have_one_durable_preparation(){
 use n::group_management::{GroupWriteOperation as Op,NativeGroupManagementConfig as Policy};let f=installed();let cfg=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),1,Some(&f.scope))).unwrap());let policy_group=Policy{set_properties:true,disband:true};let inputs=[RelationMessage::capture(&f.scope,None,&[relation(b"1_2")],&[],&[],&"a".repeat(32),policy()).unwrap(),RelationMessage::capture_management(&f.scope,GROUP,Op::Disband,&[],&"b".repeat(32),policy_group).unwrap(),RelationMessage::capture_management(&f.scope,GROUP,Op::SetProperties,&[PublicProperty{key:"Name",value:PropertyValue::Text("x")}],&"d".repeat(32),policy_group).unwrap(),RelationMessage::capture_creation(&f.scope,"name",1,b"fixture-user",&members(b"fixture-user"),&[],&"c".repeat(32),true,cpolicy()).unwrap()];let barrier=Arc::new(std::sync::Barrier::new(5));let mut threads=Vec::new();for message in inputs{let(db,run,owner,scope,gate,config,ready)=(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),f.gate.clone(),cfg.clone(),barrier.clone());threads.push(std::thread::spawn(move||{ready.wait();RelationIntent::capture(db,run,owner,scope,Arc::new(message),config,gate,Instant::now()+Duration::from_secs(30))}));}barrier.wait();let results=threads.into_iter().map(|t|t.join().unwrap()).collect::<Vec<_>>();assert_eq!(results.iter().filter(|r|matches!(r,Ok(IntentAdmission::Fresh(_)))).count(),1);assert_eq!(results.iter().filter(|r|matches!(r,Err("app_account_relation_preparing"))).count(),3);drop(results);assert_eq!(f.temp.database.with_conn(|c|n::relation_journal::intent_history(c,f.run.line_id(),128)).unwrap()[0].state,"not_sent");
}
#[test]
fn group_create_global_input_and_decode_caps_refund_only_when_last_holder_drops(){
 let f=installed();let charge=f.scope.reserve_native_rpc(n::rpc_stream::MAX_STREAM_BYTES-128).unwrap();assert!(create::CreateInput::capture(&f.scope,"x",1,b"fixture-user",&members(b"fixture-user"),&[],true).is_err());let wire=result(true,GROUP,b"");assert!(create::decode(&f.scope,0,&wire).is_err());drop(charge);let r=create::decode(&f.scope,0,&wire).unwrap();let held=r.clone();drop(r);let charged=f.scope.native_rpc_resources();assert_eq!(charged.0,1);f.scope.close();assert_eq!(f.scope.native_rpc_resources(),charged);drop(held);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
